package main

// Deterministic SVG charts from the measured rows — regenerated by every
// bench run and by -report-only, committed beside RESULTS.md. Light and dark
// variants per chart; the markdown embeds them via <picture> so GitHub
// serves the right one. Colors, ink, and mark specs follow the documented
// palette: series hues are fixed per tool across every chart, text wears
// text tokens (never the series color), marks are thin with rounded
// data-ends, gridlines are recessive hairlines.

import (
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// tool display order and fixed hue slots (identity is consistent across
// charts; a tool never changes color between figures).
var chartTools = []struct{ id, label string }{
	{"mole", "mole"},
	{"kubectl-expert", "expert kubectl"},
	{"kubectl-naive", "naive kubectl"},
	{"kubectl-status", "kubectl-status"},
}

type chartTheme struct {
	suffix     string // "" for light, "-dark"
	surface    string
	inkPrimary string
	inkSecond  string
	inkMuted   string
	grid       string
	series     map[string]string // tool id -> hex
	segSliver  string            // stacked-bar callout segment (accent)
	segBody    string            // stacked-bar body segment (light step)
}

var chartThemes = []chartTheme{
	{
		suffix: "", surface: "#fcfcfb",
		inkPrimary: "#0b0b0b", inkSecond: "#52514e", inkMuted: "#898781", grid: "#e1e0d9",
		series: map[string]string{
			"mole": "#2a78d6", "kubectl-expert": "#eb6834",
			"kubectl-naive": "#1baf7a", "kubectl-status": "#eda100",
		},
		segSliver: "#2a78d6", segBody: "#9ec5f4",
	},
	{
		suffix: "-dark", surface: "#1a1a19",
		inkPrimary: "#ffffff", inkSecond: "#c3c2b7", inkMuted: "#898781", grid: "#2c2c2a",
		series: map[string]string{
			"mole": "#3987e5", "kubectl-expert": "#d95926",
			"kubectl-naive": "#199e70", "kubectl-status": "#c98500",
		},
		segSliver: "#3987e5", segBody: "#86b6ef",
	},
}

const chartFont = `font-family="system-ui, -apple-system, 'Segoe UI', sans-serif"`

// writeCharts renders every chart in every theme into dir.
func writeCharts(dir string, rows []row) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	st := computeStats(rows)
	for _, th := range chartThemes {
		files := map[string]string{
			"accuracy" + th.suffix + ".svg":        accuracyChart(th, st),
			"tokens-vs-fleet" + th.suffix + ".svg": tokensChart(th, st),
			"time-breakdown" + th.suffix + ".svg":  timeChart(th, st),
		}
		for name, svg := range files {
			if err := os.WriteFile(filepath.Join(dir, name), []byte(svg), 0o644); err != nil {
				return err
			}
		}
	}
	return nil
}

// benchStats is everything the charts and the headline section derive from
// the rows — computed once, never hand-maintained.
type benchStats struct {
	failureScenarios int
	truthFound       map[string]int         // tool id -> scenarios with the cause found
	fanout           map[string]map[int]int // tool id -> namespaces -> tokens
	fanoutSizes      []int
	// mole medians across failure scenarios.
	medianWallMS     int64
	medianOverheadMS int64
	minOverheadMS    int64
	maxOverheadMS    int64
	maxOverheadPct   float64
	medianMoleTokens int
	medianExpertTok  int
	medianStatusTok  int
	medianExpertInv  int
}

func computeStats(rows []row) benchStats {
	st := benchStats{
		truthFound: map[string]int{},
		fanout:     map[string]map[int]int{},
	}
	seen := map[string]bool{}
	var walls, overheads []int64
	var moleTok, expertTok, statusTok, expertInv []int
	var overheadPcts []float64
	for _, r := range rows {
		if strings.HasPrefix(r.Scenario, "fanout-") {
			n, err := strconv.Atoi(strings.TrimPrefix(r.Scenario, "fanout-"))
			if err == nil {
				if st.fanout[r.Tool] == nil {
					st.fanout[r.Tool] = map[int]int{}
				}
				st.fanout[r.Tool][n] = r.Tokens
				if !contains(st.fanoutSizes, n) {
					st.fanoutSizes = append(st.fanoutSizes, n)
				}
			}
		}
		if r.Truth == "" {
			continue
		}
		if !seen[r.Scenario] {
			seen[r.Scenario] = true
			st.failureScenarios++
		}
		if r.Truth == "yes" {
			st.truthFound[r.Tool]++
		}
		switch r.Tool {
		case "mole":
			moleTok = append(moleTok, r.Tokens)
			walls = append(walls, r.WallMS)
			over := phaseMS(r.PreflightMS) + phaseMS(r.SyncMS) + phaseMS(r.DiagnoseMS) + phaseMS(r.EmitMS)
			overheads = append(overheads, over)
			if r.WallMS > 0 {
				overheadPcts = append(overheadPcts, float64(over)/float64(r.WallMS)*100)
			}
		case "kubectl-expert":
			expertTok = append(expertTok, r.Tokens)
			expertInv = append(expertInv, r.Invocations)
		case "kubectl-status":
			statusTok = append(statusTok, r.Tokens)
		}
	}
	sort.Ints(st.fanoutSizes)
	st.medianWallMS = medianI64(walls)
	st.medianOverheadMS = medianI64(overheads)
	st.minOverheadMS, st.maxOverheadMS = minMaxI64(overheads)
	for _, p := range overheadPcts {
		if p > st.maxOverheadPct {
			st.maxOverheadPct = p
		}
	}
	st.medianMoleTokens = medianInt(moleTok)
	st.medianExpertTok = medianInt(expertTok)
	st.medianStatusTok = medianInt(statusTok)
	st.medianExpertInv = medianInt(expertInv)
	return st
}

func phaseMS(s string) int64 {
	n, _ := strconv.ParseInt(s, 10, 64)
	return n
}

func contains(xs []int, x int) bool {
	for _, v := range xs {
		if v == x {
			return true
		}
	}
	return false
}

func medianI64(xs []int64) int64 {
	if len(xs) == 0 {
		return 0
	}
	s := append([]int64(nil), xs...)
	sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
	return s[len(s)/2]
}

func minMaxI64(xs []int64) (int64, int64) {
	if len(xs) == 0 {
		return 0, 0
	}
	lo, hi := xs[0], xs[0]
	for _, v := range xs[1:] {
		if v < lo {
			lo = v
		}
		if v > hi {
			hi = v
		}
	}
	return lo, hi
}

func medianInt(xs []int) int {
	if len(xs) == 0 {
		return 0
	}
	s := append([]int(nil), xs...)
	sort.Ints(s)
	return s[len(s)/2]
}

func commaInt(n int) string {
	s := strconv.Itoa(n)
	if len(s) <= 3 {
		return s
	}
	var out []byte
	for i, c := range []byte(s) {
		if i > 0 && (len(s)-i)%3 == 0 {
			out = append(out, ',')
		}
		out = append(out, c)
	}
	return string(out)
}

// accuracyChart: horizontal bars — scenarios (of the failure corpus) where
// each tool's output contained the ground-truth cause.
func accuracyChart(th chartTheme, st benchStats) string {
	const w, h = 880, 316
	plotX0, plotX1 := 170.0, 780.0
	var b strings.Builder
	svgOpen(&b, w, h, th)
	text(&b, 24, 30, th.inkPrimary, 15, 600, "start", "Found the ground-truth cause")
	text(&b, 24, 50, th.inkSecond, 12, 400, "start",
		fmt.Sprintf("of %d staged failure scenarios (crash loops, dead nodes, quota, admission, …)", st.failureScenarios))

	// Recessive vertical gridlines at 0 / 5 / 10 / 15.
	for _, tick := range []int{0, 5, 10, 15} {
		x := plotX0 + (plotX1-plotX0)*float64(tick)/float64(st.failureScenarios)
		fmt.Fprintf(&b, `<line x1="%.1f" y1="72" x2="%.1f" y2="252" stroke="%s" stroke-width="1"/>`, x, x, th.grid)
		text(&b, x, 270, th.inkMuted, 11, 400, "middle", strconv.Itoa(tick))
	}
	text(&b, (plotX0+plotX1)/2, 292, th.inkMuted, 11, 400, "middle", "failure scenarios where the output named the cause")

	y := 86.0
	for _, t := range chartTools {
		found := st.truthFound[t.id]
		bw := (plotX1 - plotX0) * float64(found) / float64(st.failureScenarios)
		text(&b, plotX0-10, y+15, th.inkSecond, 12, 400, "end", t.label)
		roundedRightBar(&b, plotX0, y, bw, 20, th.series[t.id])
		label := fmt.Sprintf("%d/%d", found, st.failureScenarios)
		if found < st.failureScenarios {
			label += fmt.Sprintf(" (%d%%)", int(math.Round(float64(found)/float64(st.failureScenarios)*100)))
		}
		text(&b, plotX0+bw+8, y+15, th.inkPrimary, 12, 600, "start", label)
		y += 42
	}
	b.WriteString("</svg>\n")
	return b.String()
}

// tokensChart: log-log lines — output tokens as the fleet grows. The story
// is the flat blue line; identity rides the fixed tool hues plus a legend
// and end-of-line labels.
func tokensChart(th chartTheme, st benchStats) string {
	const w, h = 880, 430
	plotX0, plotX1 := 84.0, 720.0
	plotY0, plotY1 := 96.0, 356.0
	var b strings.Builder
	svgOpen(&b, w, h, th)
	text(&b, 24, 30, th.inkPrimary, 15, 600, "start", "Output stays flat as the fleet grows")
	text(&b, 24, 50, th.inkSecond, 12, 400, "start", "tokens of combined output for one fan-out check")

	// Legend row (color chips + names).
	lx := 24.0
	for _, t := range chartTools {
		fmt.Fprintf(&b, `<rect x="%.1f" y="62" width="10" height="10" rx="2" fill="%s"/>`, lx, th.series[t.id])
		text(&b, lx+15, 71, th.inkSecond, 11, 400, "start", t.label)
		lx += 15 + 7.2*float64(len(t.label)) + 18
	}

	xFor := func(n int) float64 {
		lo, hi := math.Log10(float64(st.fanoutSizes[0])), math.Log10(float64(st.fanoutSizes[len(st.fanoutSizes)-1]))
		return plotX0 + (plotX1-plotX0)*(math.Log10(float64(n))-lo)/(hi-lo)
	}
	yFor := func(tok int) float64 {
		lo, hi := 2.0, 7.0 // 100 .. 10,000,000
		return plotY1 - (plotY1-plotY0)*(math.Log10(float64(tok))-lo)/(hi-lo)
	}

	// Axis titles live on the axes, not the subtitle.
	text(&b, 24, plotY0-10, th.inkMuted, 11, 400, "start", "output tokens (log scale)")

	// Horizontal gridlines per decade.
	for d := 2; d <= 7; d++ {
		yy := yFor(int(math.Pow(10, float64(d))))
		fmt.Fprintf(&b, `<line x1="%.1f" y1="%.1f" x2="%.1f" y2="%.1f" stroke="%s" stroke-width="1"/>`, plotX0, yy, plotX1, yy, th.grid)
		text(&b, plotX0-8, yy+4, th.inkMuted, 11, 400, "end", decadeLabel(d))
	}
	for _, n := range st.fanoutSizes {
		text(&b, xFor(n), plotY1+22, th.inkMuted, 11, 400, "middle", commaInt(n))
	}
	text(&b, (plotX0+plotX1)/2, plotY1+44, th.inkMuted, 11, 400, "middle", "namespaces checked (log scale)")

	// Lines, end markers, and collision-nudged end labels.
	type endLabel struct {
		y     float64
		color string
		text  string
	}
	var ends []endLabel
	for _, t := range chartTools {
		pts := st.fanout[t.id]
		if len(pts) == 0 {
			continue
		}
		var path strings.Builder
		for i, n := range st.fanoutSizes {
			cmd := "L"
			if i == 0 {
				cmd = "M"
			}
			fmt.Fprintf(&path, "%s%.1f %.1f ", cmd, xFor(n), yFor(pts[n]))
		}
		fmt.Fprintf(&b, `<path d="%s" fill="none" stroke="%s" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`, strings.TrimSpace(path.String()), th.series[t.id])
		last := st.fanoutSizes[len(st.fanoutSizes)-1]
		fmt.Fprintf(&b, `<circle cx="%.1f" cy="%.1f" r="4" fill="%s"/>`, xFor(last), yFor(pts[last]), th.series[t.id])
		ends = append(ends, endLabel{y: yFor(pts[last]), color: th.series[t.id], text: commaInt(pts[last])})
	}
	// Nudge labels apart top-down so none overlap (≥16px separation).
	sort.Slice(ends, func(i, j int) bool { return ends[i].y < ends[j].y })
	for i := 1; i < len(ends); i++ {
		if ends[i].y-ends[i-1].y < 16 {
			ends[i].y = ends[i-1].y + 16
		}
	}
	for _, e := range ends {
		fmt.Fprintf(&b, `<rect x="%.1f" y="%.1f" width="8" height="8" rx="2" fill="%s"/>`, plotX1+10, e.y-4, e.color)
		text(&b, plotX1+23, e.y+4, th.inkSecond, 11, 400, "start", e.text)
	}
	b.WriteString("</svg>\n")
	return b.String()
}

// timeChart: one stacked horizontal bar decomposing mole's median wall —
// the overhead sliver against the evidence window, percentages spelled out.
func timeChart(th chartTheme, st benchStats) string {
	const w, h = 880, 250
	barX0, barX1, barY := 24.0, 856.0, 108.0
	var b strings.Builder
	svgOpen(&b, w, h, th)
	text(&b, 24, 30, th.inkPrimary, 15, 600, "start", "Where mole's time goes (median failure scenario)")
	text(&b, 24, 50, th.inkSecond, 12, 400, "start", "the wall clock is not tool cost — it is the deliberate wait for settle evidence")

	total := float64(st.medianWallMS)
	overW := (barX1 - barX0) * float64(st.medianOverheadMS) / total
	if overW < 3 {
		overW = 3
	}
	overPct := float64(st.medianOverheadMS) / total * 100
	// Overhead sliver (accent), 2px surface gap, then the evidence window.
	fmt.Fprintf(&b, `<rect x="%.1f" y="%.1f" width="%.1f" height="24" fill="%s"/>`, barX0, barY, overW, th.segSliver)
	roundedRightBar(&b, barX0+overW+2, barY, barX1-barX0-overW-2, 24, th.segBody)
	// Callout for the sliver.
	fmt.Fprintf(&b, `<line x1="%.1f" y1="%.1f" x2="%.1f" y2="%.1f" stroke="%s" stroke-width="1"/>`, barX0+overW/2, barY-4, barX0+overW/2, barY-16, th.inkMuted)
	text(&b, barX0+overW/2+6, barY-20, th.inkPrimary, 12, 600, "start",
		fmt.Sprintf("tool overhead: %d ms (%s%%)", st.medianOverheadMS, trimPct(overPct)))
	// Evidence window label inside the body segment (dark ink both modes —
	// the body step is light in both).
	text(&b, barX0+(barX1-barX0)/2, barY+16, "#0b0b0b", 12, 600, "middle",
		fmt.Sprintf("evidence window: %.1f s (%s%%)", float64(st.medianWallMS-st.medianOverheadMS)/1000, trimPct(100-overPct)))
	text(&b, barX0, barY+46, th.inkMuted, 11, 400, "start", "0 s")
	text(&b, barX1, barY+46, th.inkMuted, 11, 400, "end", fmt.Sprintf("%.1f s", total/1000))

	text(&b, 24, barY+82, th.inkSecond, 12, 400, "start",
		fmt.Sprintf("Across every failure scenario the overhead is %d–%d ms — at most %.1f%% of the wall. The snapshot", st.minOverheadMS, st.maxOverheadMS, st.maxOverheadPct))
	text(&b, 24, barY+100, th.inkSecond, 12, 400, "start",
		"baselines are timed after the failure is already steady; the wait that got the operator there is unmeasured.")
	b.WriteString("</svg>\n")
	return b.String()
}

func decadeLabel(d int) string {
	switch d {
	case 2:
		return "100"
	case 3:
		return "1k"
	case 4:
		return "10k"
	case 5:
		return "100k"
	case 6:
		return "1M"
	}
	return "10M"
}

func trimPct(p float64) string {
	s := strconv.FormatFloat(p, 'f', 1, 64)
	return strings.TrimSuffix(s, ".0")
}

func svgOpen(b *strings.Builder, w, h int, th chartTheme) {
	fmt.Fprintf(b, `<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d" role="img">`, w, h, w, h)
	fmt.Fprintf(b, `<rect width="%d" height="%d" rx="8" fill="%s"/>`, w, h, th.surface)
}

// roundedRightBar draws a horizontal bar with a 4px rounded data-end on the
// right and a square baseline on the left.
func roundedRightBar(b *strings.Builder, x, y, w, h float64, fill string) {
	r := 4.0
	if w < r {
		r = w / 2
	}
	fmt.Fprintf(b, `<path d="M%.1f %.1f h%.1f a%.1f %.1f 0 0 1 %.1f %.1f v%.1f a%.1f %.1f 0 0 1 -%.1f %.1f h-%.1f z" fill="%s"/>`,
		x, y, w-r, r, r, r, r, h-2*r, r, r, r, r, w-r, fill)
}

func text(b *strings.Builder, x, y float64, color string, size, weight int, anchor, s string) {
	fmt.Fprintf(b, `<text x="%.1f" y="%.1f" fill="%s" font-size="%d" font-weight="%d" text-anchor="%s" %s>%s</text>`,
		x, y, color, size, weight, anchor, chartFont, escapeXML(s))
}

func escapeXML(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")
	return r.Replace(s)
}
